// Единственное место с настройками. Поддомен уже подставлен.
const now = new Date();
const monthFrom = Math.floor(new Date(now.getFullYear(), now.getMonth(), 1).getTime() / 1000);
return [{ json: {
  subdomain: 'macridin',
  planTarget: 17000000,
  convGoal: 80,
  convDeadline: '18 ноября',
  monthFrom
} }];

// Собирает ответ для Shumm и заодно отдаёт справочник воронок.
const cfg = $('Настройки').first().json;
const pipes = $('Воронки').all().flatMap(i => i.json?._embedded?.pipelines ?? []);
const leads = $('Сделки за месяц').all().flatMap(i => i.json?._embedded?.leads ?? []);
const users = $('Менеджеры').all().flatMap(i => i.json?._embedded?.users ?? []);

const WON = 142, LOST = 143;

// Статусы по всем воронкам: id -> {sort, pipeline_id, name}
const stage = {};
const ref = [];
for (const p of pipes) {
  const sts = p._embedded?.statuses ?? [];
  ref.push({ pipeline: p.name, id: p.id, statuses: sts.map(s => ({ id: s.id, name: s.name, sort: s.sort })) });
  for (const s of sts) stage[s.id] = { sort: s.sort, pipeline: p.id, name: s.name };
}

// Ищем этапы по названию, без ручных идентификаторов.
const find = (re) => Object.entries(stage).filter(([, s]) => re.test(s.name)).map(([id, s]) => ({ id: +id, ...s }));
const qualSt = find(/квал/i);
const measSt = find(/замер/i);
const warnings = [];
if (!qualSt.length) warnings.push('не найден этап со словом «квал»');
if (!measSt.length) warnings.push('не найден этап со словом «замер»');

const minSort = (list, pipeline) => {
  const own = list.filter(s => s.pipeline === pipeline);
  return own.length ? Math.min(...own.map(s => s.sort)) : null;
};
// Сделка считается дошедшей до этапа, если её статус не раньше по порядку или уже выигран.
const reached = (lead, list) => {
  if (lead.status_id === WON) return true;
  if (lead.status_id === LOST) return false;
  const st = stage[lead.status_id];
  if (!st) return false;
  const need = minSort(list, st.pipeline);
  return need === null ? false : st.sort >= need;
};

const alive = leads.filter(l => l.status_id !== LOST);
const quals = qualSt.length ? alive.filter(l => reached(l, qualSt)).length : alive.length;
const measures = measSt.length ? alive.filter(l => reached(l, measSt)).length : 0;
const contracts = leads.filter(l => l.status_id === WON).length;
const done = leads.filter(l => l.status_id === WON).reduce((s, l) => s + (l.price || 0), 0);

const byUser = {};
for (const l of alive) {
  const id = l.responsible_user_id;
  byUser[id] = byUser[id] || { total: 0, won: 0 };
  byUser[id].total++;
  if (l.status_id === WON) byUser[id].won++;
}
const initials = (n = '') => n.split(' ').filter(Boolean).slice(0, 2).map(p => p[0].toUpperCase() + '.').join(' ');
const managers = users
  .filter(u => byUser[u.id])
  .map(u => ({ name: initials(u.name), area: '', pct: Math.round(byUser[u.id].won / byUser[u.id].total * 100) }))
  .sort((a, b) => b.pct - a.pct);

const HOUR = 3600, nowS = Math.floor(Date.now() / 1000);
const problems = alive
  .filter(l => l.status_id !== WON && nowS - (l.updated_at || l.created_at || nowS) > 48 * HOUR)
  .sort((a, b) => (a.updated_at || 0) - (b.updated_at || 0))
  .slice(0, 5)
  .map(l => ({
    id: String(l.id),
    title: l.name || ('Сделка №' + l.id),
    note: 'без касания, ' + (stage[l.status_id]?.name || 'этап неизвестен'),
    age: Math.round((nowS - (l.updated_at || nowS)) / HOUR) + ' ч',
    level: 'bad'
  }));

return [{ json: {
  updated: new Date().toISOString(),
  plan: { target: cfg.planTarget, done },
  conversion: {
    current: quals ? Math.round(measures / quals * 100) : 0,
    goal: cfg.convGoal,
    deadline: cfg.convDeadline,
    history: []
  },
  funnel: { quals, measures, contracts },
  managers,
  problems,
  warnings,
  _ref: ref
} }];
